use pink_lemonade_wasm::MergeResult;
use super::fixture::{SCREEN_H, SCREEN_W, SIGMA_PX};

pub struct Sample {
    pub x: f64,
    pub y: f64,
    pub original_density: f64,
}

pub struct Quality {
    pub output_count: usize,
    pub reduction_percent: f64,
    pub normalized_mean_absolute_error_percent: f64,
}

/// Read the original mixture densities generated by `generate_quality_pixels`.
pub fn saved_samples() -> Vec<Sample> {
    let samples: Vec<Sample> = include_str!("../data/quality_pixels.csv")
        .lines()
        .skip(1)
        .map(|line| {
            let mut fields = line.split(',');
            let x = fields.next().unwrap().parse().unwrap();
            let y = fields.next().unwrap().parse().unwrap();
            let original_density = fields.next().unwrap().parse().unwrap();
            Sample { x, y, original_density }
        })
        .collect();
    assert_eq!(samples.len(), 1_000, "regenerate quality_pixels.csv");
    samples
}

/// Mean absolute density difference divided by mean original density.
/// Only the saved occupied pixels are evaluated; 0% is exact.
pub fn evaluate(input_count: usize, result: &MergeResult, samples: &[Sample]) -> Quality {
    assert!(input_count > 0 && !samples.is_empty());
    let output_count = result.count() as usize;
    let instances = result.gpu_instances();
    assert_eq!(instances.len(), output_count * 7);

    let mut absolute_error = 0.0;
    let mut original_total = 0.0;
    for sample in samples {
        let reduced = reduced_density(&instances, sample.x, sample.y);
        absolute_error += (reduced - sample.original_density).abs();
        original_total += sample.original_density;
    }
    assert!(original_total > 0.0);

    Quality {
        output_count,
        reduction_percent: 100.0 * (1.0 - output_count as f64 / input_count as f64),
        normalized_mean_absolute_error_percent: 100.0 * absolute_error / original_total,
    }
}

fn reduced_density(instances: &[f32], px: f64, py: f64) -> f64 {
    instances
        .chunks_exact(7)
        .map(|kernel| {
            let dx = (px - kernel[0] as f64 * SCREEN_W) / SIGMA_PX;
            let dy = (py - kernel[1] as f64 * SCREEN_H) / SIGMA_PX;
            let p00 = kernel[3] as f64;
            let p01 = kernel[4] as f64;
            let p11 = kernel[6] as f64;
            let det = p00 * p11 - p01 * p01;
            assert!(det > 0.0, "output covariance must be positive definite");
            let distance_squared = (p11 * dx * dx - 2.0 * p01 * dx * dy + p00 * dy * dy) / det;
            kernel[2] as f64 * (-0.5 * distance_squared).exp()
        })
        .sum()
}
